prepared:
foreach ($product in @('plumb', 'ectropy')) {
  $manager = Join-Path $env:RUNNER_TEMP "manage-$product.ps1"
  Invoke-WebRequest "https://releases.$product.perish.uk/manage.ps1" -OutFile $manager
  & $manager install --channel stable
  if ($LASTEXITCODE -ne 0) { throw "$product stable installation failed" }
}
(Join-Path $HOME '.local/bin') | Out-File -FilePath $env:GITHUB_PATH -Append
